using System;using UnityEngine;
namespace LWS.TruckBuzkashi.Editor {public static class BuzFixtures {public static void Run(){int n=0;Action<bool,string> c=(ok,label)=>{if(!ok)throw new Exception("Buz fixture "+label);n++;};c(BuzRules.EntireCargo(new Bounds(new Vector3(0,2,-49),new Vector3(3,3,5)),0),"full cargo in own corral");c(!BuzRules.EntireCargo(new Bounds(new Vector3(11,2,-49),new Vector3(3,3,5)),0),"centre-only protrusion rejected");c(!BuzRules.EntireCargo(new Bounds(new Vector3(0,2,-49),new Vector3(3,3,5)),1),"wrong team corral");c(BuzRules.EntireCargo(new Bounds(new Vector3(0,2,49),new Vector3(3,3,5)),1),"orange corral");c(BuzRules.Breaks(0,0,3,5),"genuine opposing normal impact breaks");c(!BuzRules.Breaks(0,0,1,20),"friendly impact preserves tow");c(!BuzRules.Breaks(0,0,3,2.29f),"gentle contact not a break");c(!BuzRules.Breaks(0,1,3,20),"unrelated truck collision not a break");Debug.Log("BUZ_RULE_FIXTURES_PASS count="+n);}}}
